def host_from_uri(uri):
    """Extract host and port from URI.

    Returns a tuple of (host, port) where port is a string.
    Default ports are provided when none is present in the URI.
    """
    default_ports = {
        'http': '80',
        'https': '443',
    }

    parsed = urlparse(uri)
    host = parsed.hostname
    port = parsed.port

    if port:
        return (host, str(port))
    else:
        scheme = parsed.scheme.lower()
        return (host, default_ports.get(scheme, '80'))
